from __future__ import annotations
from decimal import Decimal, InvalidOperation

def split_installments(total: str, n: int) -> list[Decimal]:
    # Validate n: must be int (not bool) and >= 1.
    if isinstance(n, bool):
        raise ValueError("n must be an integer >= 1")
    if not isinstance(n, int):
        raise ValueError("n must be an integer >= 1")
    if n < 1:
        raise ValueError("n must be an integer >= 1")
    # Validate total: must be str parseable as finite Decimal >= 0 with <= 2 decimals.
    if not isinstance(total, str):
        raise ValueError("total must be a decimal string")
    try:
        d = Decimal(total)
    except (InvalidOperation, ValueError, ArithmeticError, TypeError, AttributeError):
        raise ValueError("invalid total")
    # Must be finite (rejects NaN, sNaN, Infinity).
    if not d.is_finite():
        raise ValueError("total must be finite")
    # Must be >= 0.
    if d < 0:
        raise ValueError("total must be >= 0")
    # Must have at most 2 decimal places.
    exp = d.as_tuple().exponent
    # For finite values exponent is int; guard anyway.
    if isinstance(exp, int):
        if exp < 0 and -exp > 2:
            raise ValueError("total must have at most 2 decimal places")
    else:
        raise ValueError("invalid total")
    # Convert to integer cents exactly (scaleb is exact, no float).
    # Since validated <= 2 decimals, d * 100 is integral.
    total_cents = int(d.scaleb(2))
    base, rem = divmod(total_cents, n)
    result: list[Decimal] = []
    for i in range(n):
        cents = base + 1 if i < rem else base
        # scaleb(-2) gives exponent -2 exactly (e.g. 5 -> 0.05).
        amt = Decimal(cents).scaleb(-2)
        result.append(amt)
    return result
